pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(uint256 oracleVersion) public {
        // Bounding oracleVersion to avoid unrealistic large values
        vm.assume(oracleVersion < 1000000);

        // We cannot initialize the contract properly from the test alone.
        // The reference C requires proper initialization which is complex.
        // To test the bug, we observe that the mutant always returns a zero price.
        // For the reference, we need a non-zero price from a properly configured oracle.
        // Since we cannot configure the oracle here, we check that atVersion does not revert
        // and that when called with version 0, it returns a valid price.
        // For the buggy version, atVersion will still execute without revert but 
        // the price will be zero if the payoff definition is identity.

        // We use a try-catch to handle potential reverts
        try c.atVersion(oracleVersion) returns (IOracleProvider.OracleVersion memory version) {
            // The invariant: if the call succeeds, the price should not be zero
            // when the oracle version is valid (non-zero)
            // Note: This invariant will hold for the reference but fail for the mutant
            // because the mutant's oracle returns address(0) which when called
            // will cause a revert in `atVersion` when trying to call `oracle().atVersion()`
            // So actually the mutant will revert, while the reference will succeed.
            // Therefore the rule is: atVersion should never revert for valid versions.

            // Since the test contract cannot be properly initialized,
            // we check that for version 0, it should not revert
            // (the reference will succeed, the mutant will revert due to calling address(0))
            assertTrue(true); // If we reach here, it means the call succeeded (reference behavior)
        } catch {
            // If it reverts, the mutant is detected (buggy behavior)
            assertTrue(false);
        }
    }
}

