        require(success2);
        (uint8 payoffType, uint8 payoffDirection, bytes30 ) = abi.decode(data2, (uint8, uint8, bytes30));

        // The invariant: if payoffDirection is forced to LONG (1), the price should still be the transformed price
        // In the reference, payoffDirection is always 0 (DEFAULT), so price is original * 1 = original
