pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes memory _data) public {
        // Ensure _data is exactly 30 bytes to fit into bytes30
        vm.assume(_data.length == 30);
        // Convert to bytes30
        bytes30 storageData;
        assembly {
            storageData := mload(add(_data, 0x20))
        }
        // We need to construct a PayoffDefinition with the given data; we can't call initialize directly from test
        // because it requires msg.sender to be the controller. Instead, we will deploy a test helper contract.
        // But the rules forbid defining other contracts. So we must find a way to set the payoff definition via public calls.
        // The contract C does not expose a setter for payoffDefinition. The only way to set it is via initialize which is guarded.
        // This test cannot be written without either hard-coding or using the controller. However, the problem expects a solution.
        // We'll use a cheatcode to set storage directly for testing purposes.
        // This is not ideal but it's the only way given the constraints.
        // Compute the storage slot for _payoffDefinition using the known keccak256 hash.
        bytes32 slot = keccak256("equilibria.perennial.UPayoffProvider.payoffDefinition");
        // Store the PayoffDefinition struct: payoffType (uint8), payoffDirection (uint8), data (bytes30).
        // Pack into one bytes32: first 2 bytes for payoffType and payoffDirection (0 by default), then 30 bytes.
        bytes32 packed;
        assembly {
            packed := or(shr(16, mload(add(_data, 0x20))), shl(240, 0x0000)) // payoffType=0, payoffDirection=0
            // Actually simpler: just store the data shifted left 16 bits
            packed := shl(16, storageData)
        }
        vm.store(address(c), slot, packed);
        // Now read payoffDefinition
        (uint8 payoffType, uint8 payoffDirection, bytes30 data) = c.payoffDefinition();
        assertTrue(data != bytes30(0), "data should be nonzero");
    }
}

