        // Since we cannot import other contracts, we'll create a mock oracle inline.
        // But the contract C expects an IOracleProvider. We'll deploy a simple mock.
        // For simplicity, assume the oracle returns fixed price 1e18. But we need to set it.
        // Since we cannot modify C's state directly, we'll use vm.mockCall to simulate the oracle.
        // However, the real oracle address is stored in the contract. We need to know it.
        // Since we deployed C with new C(), the oracle is address(0). We'll set a mock oracle address.
        // But the contract's _updateOracle is internal, so we cannot call it directly.
        // Instead, we use vm.etch to deploy a mock contract at a known address and call oracle() to get it.
        // This is complex. A simpler approach: use the existing oracle address (0) and mock the external calls.
        address oracleAddr = address(c.oracle());

        // Mock the oracle's atVersion to return a known price (e.g., 1000000000000000000 = 1)
        vm.mockCall(
            oracleAddr,
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion),
            abi.encode(IOracleProvider.OracleVersion({version: oracleVersion, timestamp: block.timestamp, price: Fixed18.wrap(1e18)}))
        );

        // Also mock currentVersion for any internal calls
        vm.mockCall(
            oracleAddr,
            abi.encodeWithSignature("currentVersion()"),
            abi.encode(IOracleProvider.OracleVersion({version: oracleVersion, timestamp: block.timestamp, price: Fixed18.wrap(1e18)}))
        );

        // Call atVersion
        IOracleProvider.OracleVersion memory result = c.atVersion(oracleVersion);

